<?php
require 'config.php';require 'includes/functions.php';$pageTitle='Shop';
$cats=['Men Perfumes','Women Perfumes','Home Diffusers','Car Diffusers','Car & Home Fresheners'];$category=trim($_GET['category']??'');$q=trim($_GET['q']??'');
$sql='SELECT * FROM products WHERE active=1';$params=[];
if(in_array($category,$cats,true)){$sql.=' AND category=?';$params[]=$category;}
if($q!==''){$sql.=' AND (name LIKE ? OR description LIKE ?)';$params[]="%$q%";$params[]="%$q%";}
$sql.=' ORDER BY created_at DESC';$st=$pdo->prepare($sql);$st->execute($params);$products=$st->fetchAll();require 'includes/header.php';?>
<section class="hero"><div class="eyebrow">Find your signature scent</div><h1>Fragrance that makes every moment feel special.</h1><p>Shop perfumes, home diffusers and fresheners for your car and home. Browse freely — registration is only required when you are ready to order.</p><a class="btn" href="#products">Explore products</a></section>
<div class="section-head"><div><div class="eyebrow">Our collection</div><h2 id="products">Shop fragrances</h2></div><form method="get" class="actions"><input name="q" value="<?=e($q)?>" placeholder="Search products..." style="padding:10px;border:1px solid #ddd;border-radius:8px"><button class="btn">Search</button></form></div>
<form method="get" class="field" style="max-width:320px"><label>Filter by category</label><select name="category" onchange="this.form.submit()"><option value="">All categories</option><?php foreach($cats as $c):?><option value="<?=e($c)?>" <?=$category===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></form>
<?php if(!$products):?><div class="panel"><h3>No products to show yet</h3><p class="muted">The administrator can add products and photos in the admin area.</p></div><?php else:?><div class="grid"><?php foreach($products as $p):?><article class="product"><div class="product-image"><?php if($p['image']&&is_file($p['image'])):?><img src="<?=e($p['image'])?>" alt="<?=e($p['name'])?>"><?php else:?><span class="no-image">Product photo coming soon</span><?php endif;?></div><div class="product-info"><div class="category"><?=e($p['category'])?></div><h3><?=e($p['name'])?></h3><div class="price"><?=money($p['price'])?></div><?php if($p['description']):?><p class="muted small"><?=e($p['description'])?></p><?php endif;?><a class="btn" href="product.php?id=<?=$p['id']?>">View product</a></div></article><?php endforeach;?></div><?php endif;?><?php require 'includes/footer.php';?>